    await page.goto(url, wait_until="domcontentloaded")
    print(f"[guba][list] 等待列表数据或验证码信号: page={page_no}")
    await page.wait_for_function(
        "() => (window.article_list && Array.isArray(window.article_list.re)) || window.__captcha_detected__"
