async def _fetch_post_content(page, code: str, post_id: int, *, has_comments: bool = True) -> tuple[str, list[dict]]:
    """导航到帖子页，拦截页面自身发出的评论请求，返回 (正文纯文本, 评论原始列表)。"""
    collected: list[dict] = []

    async def _on_response(response) -> None:
        if "ArticleNewReplyList" not in response.url:
            return
        try:
            data = await response.json()
            if isinstance(data.get("re"), list):
                collected.extend(data["re"])
        except Exception:  # noqa: BLE001
            pass

    page.on("response", _on_response)
    try:
        url = f"https://guba.eastmoney.com/news,{code},{int(post_id)}.html"
        print(f"[guba][post] 导航帖子页: post_id={post_id} url={url}")
        await page.goto(url, wait_until="domcontentloaded")
        print(f"[guba][post] 等待正文数据或验证码信号: post_id={post_id}")
        await page.wait_for_function(
            "() => (window.post_article && typeof window.post_article.post_content === 'string') || window.__captcha_detected__"
        )
        if await page.evaluate("() => Boolean(window.__captcha_detected__)"):
            print(f"[警告] 帖子页检测到验证码（帖子 {post_id}）")
            raise CaptchaError("captcha on post page")
        html_text = await page.evaluate("() => window.post_article.post_content")
        # 评论 XHR 在内容渲染后异步触发，等待其到达；无评论则跳过
        if has_comments:
            await page.wait_for_timeout(3000)
        print(
            f"[guba][post] 帖子数据就绪: post_id={post_id} comments_collected={len(collected)}"
        )
        return _strip_html(html_text), list(collected)
    finally:
        page.remove_listener("response", _on_response)


def _normalize_comment(raw_comment: dict) -> dict:
    return {
