    }


def _normalize_post(raw_post: dict, post_text: str, comments: list[dict]) -> dict:
    return {
        "post_id": raw_post.get("post_id"),
        "title": raw_post.get("post_title", ""),
        "post_text": post_text,
        "author": raw_post.get("user_nickname", ""),
        "created_iso": _to_iso_utc8(raw_post.get("post_publish_time")),
        "like_count": 0,
        "reply_count": int(raw_post.get("post_comment_count") or 0),
        "comments": comments,
        "source": "guba",
    }


async def fetch_guba_for_date(page, code: str, date: str) -> list[dict]:
    """抓取指定日期帖子，逐页遍历并在日期越界时停止。"""
    target_date = str(date)
    page_no = 1
    posts: list[dict] = []
    seen_post_ids: set[Any] = set()
    found_target_any = False
    max_pages = 200

    while page_no <= max_pages:
        try:
            raw_list = await _fetch_post_list(page, code, page_no)
        except CaptchaError:
            raise
        except Exception:  # noqa: BLE001
            page_no += 1
            continue

        if not raw_list:
            break

        added_on_page = 0
        has_older = False
        for raw_post in raw_list:
            publish_time = str(raw_post.get("post_publish_time") or "")
            post_date = publish_time[:10]
            if post_date and post_date < target_date:
                has_older = True
                continue  # 不 break：当页可能混有目标日期帖子，后续页可能也有
            if post_date and post_date != target_date:
                continue

            post_id = raw_post.get("post_id")
            if post_id in seen_post_ids:
                continue
            reply_count = int(raw_post.get("post_comment_count") or 0)
            try:
                post_text, raw_comments = await _fetch_post_content(
                    page, code, int(post_id), has_comments=reply_count > 0
                )
            except Exception:  # noqa: BLE001
                continue

            comments = [_normalize_comment(item) for item in (raw_comments or [])]
            posts.append(_normalize_post(raw_post, post_text, comments))
            seen_post_ids.add(post_id)
            added_on_page += 1

        # 整页都比目标日期更早且没有目标帖子 → 已翻过头，停止
        if found_target_any and has_older and added_on_page == 0:
            break
        if not has_older and added_on_page == 0:
            page_no += 1
            continue
        if added_on_page > 0:
            found_target_any = True
        page_no += 1

