async def _prepare_incremental_resume(
    app: Any,
    config: dict[str, Any],
    *,
    target_max_posts: int,
) -> int:
    """When thread exists, continue crawling from saved cursor and append target_max_posts."""
    snap = await app.aget_state(config)
    values = dict((snap.values or {}))
    if not values:
        return max(1, int(target_max_posts or 1))

    existing_posts = list(values.get("posts") or [])
    existing_count = len(existing_posts)
    append_count = max(1, int(target_max_posts or 1))
    target = existing_count + append_count
    detail_index = int(values.get("detail_index") or existing_count)

    update: dict[str, Any] = {"max_posts": target}
    # Re-open list/detail loop so old thread_id can continue from saved cursor.
    update.update(
        {
            "posts_done": False,
            "details_done": False,
            "ready_for_next_step": False,
            "detail_index": detail_index,
        }
    )
    print(
        "[恢复] 检测到旧 thread，按游标续抓新增帖子: "
        f"existing_posts={existing_count}, append_max_posts={append_count}, "
        f"target_total_posts={target}, "
        f"resume_from_posts_page={int(values.get('posts_page') or 1)}"
    )

    await app.aupdate_state(config, update)
    return target


