from __future__ import annotations

import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any


def _iso_now() -> str:
    return datetime.now(UTC).isoformat().replace("+00:00", "Z")


def _parse_iso_datetime(value: str) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        if text.endswith("Z"):
            text = f"{text[:-1]}+00:00"
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def _atomic_write_json(path: Path, payload: dict[str, Any]) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_suffix(f"{path.suffix}.tmp")
    tmp_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp_path.replace(path)
    return path


def _build_posts_block(state: dict[str, Any]) -> dict[str, Any] | None:
    posts_raw = state.get("posts")
    if isinstance(posts_raw, dict):
        items = list(posts_raw.get("items") or [])
        block: dict[str, Any] = {
            "count": int(posts_raw.get("count") or len(items)),
            "items": items,
            "meta": dict(posts_raw.get("meta") or {}),
        }
        return block

    if isinstance(posts_raw, list):
        run_started_at = str(state.get("run_started_at") or "").strip() or _iso_now()
        started_dt = _parse_iso_datetime(run_started_at)
        now_dt = datetime.now(UTC)
        run_duration_seconds = 0
        if started_dt is not None:
            if started_dt.tzinfo is None:
                started_dt = started_dt.replace(tzinfo=UTC)
            run_duration_seconds = max(0, int((now_dt - started_dt).total_seconds()))

        return {
            "count": len(posts_raw),
            "items": list(posts_raw),
            "meta": {
                "thread_id": str(state.get("thread_id") or ""),
                "run_duration_seconds": run_duration_seconds,
            },
        }

    return None


def persist_report(state: dict[str, Any], *, path: str | Path | None = None) -> Path | None:
    """Persist unified report schema used by main/analyze/insight flows."""
    output_path = str(path or state.get("output_path") or "").strip()
    if not output_path:
        return None

    posts_block = _build_posts_block(state)
    payload: dict[str, Any] = {
        "schema_version": "1.0",
        "symbol": str(state.get("symbol") or state.get("stock") or "").upper().strip(),
        "scraped_at": str(state.get("scraped_at") or state.get("run_started_at") or _iso_now()),
    }
    if posts_block is not None:
        payload["posts"] = posts_block

    for key in (
        "daily",
        "analyzed_at",
        "core_concepts",
        "rating_trend",
        "profit_forecast_change",
    ):
        if key in state:
